    "a": "答：功就是作用在物体上的力和物体在该力作用下所移动\n的距离这两者的乘积。它的单位是：焦耳（J\n也可用牛顿²米）\n（N²m）；单位时间所作的功，叫做功率，其单位是：瓦特（W）\n也可用焦耳/秒（J/s）。",
