    "id": "Lb5C2031",
    "type": "C",
    "type_name": "简答题",
    "q": "什么叫汽化和汽化压强？水发生汽化的条件\n是什么？",
    "a": "答：汽化是指液体分子有足够的动能可以从它的自由表面\n不断发射出来而成为蒸汽或沸腾的现象。汽化时液体所具有的\n向外扩张叫汽化压强，当外界压强大于水的汽化压强时，液体\n就不会发生汽化。",
    "o": null,
    "q_img": "q1_question_images/Lb5C2031_q.png",
