    "id": "Lb5C2034",
    "type": "C",
    "type_name": "简答题",
    "q": "试述静水压强的两个特性。",
    "a": "答：静水内部任何一点各方向的压强大小是相等的，它与\n作用面的方位无关，这是第一特性；静水压强的方向是垂直并\n指向作用面，这是第二特性。",
    "o": null,
    "q_img": "q1_question_images/Lb5C2034_q.png",
