    "type_name": "简答题",
    "q": "事故处理的主要任务是什么？",
    "a": "答：（1）迅速限制事故扩大，立即解除对人身和设备的危\n害；\n（2）设法保证厂用电源，尽力维护设备继续运行；\n（3）尽快恢复重要用户供电；\n（4）恢复正常运行方式。",
