    "type": "C",
    "type_name": "简答题",
    "q": "发电机非同步并列对发电机有什么后果？",
    "a": "答：发电机非同步并列合闸瞬间，发电机和所连接的设备\n\n将承受20～30 倍额定电流作用下所产生的电动力和发热量，会\n造成发电机定子绕组变形、扭弯、绝缘崩裂、绕组接头处熔化\n等，严重时会使发电机损坏烧毁。",
    "o": null,
