    "type": "C",
    "type_name": "简答题",
    "q": "变压器事故过负荷运行有何危害？",
    "a": "答：变压器事故过负荷的主要危害是：引起变压器绕组温\n度和温升超过允许值，使绝缘老化加快，变压器寿命缩短，变\n压器事故过负荷的时间和数值由制造厂家规定。",
