    "id": "Lb3C2048",
    "type": "C",
    "type_name": "简答题",
    "q": "同步发电机不对称运行时，有什么影响？",
    "a": "答：主要影响是：\n（1）对发电机本身而言，其负序电流将引起定子电流某一\n相可能超过额定值和引起转子的附加发热和机械振动并伴有噪\n声。\n（2）对用户的影响。由于不对称的电压加于负载时，将影\n响用电设备的效率，从而影响生产。",
    "o": null,
