    "q": "在电压相同的情况下，如果将一个直流电磁铁\n接在交流回路上，将会发生什么后果？",
    "a": "答：把直流电磁铁接到交流回路上，因为有电阻和电感的\n共同作用，即阻抗的作用，将使流过线圈的电流变小，铁芯中\n磁场变弱，使电磁铁的可动部分不被吸动或不能正常工作。",
