    "type": "C",
    "type_name": "简答题",
    "q": "设备检修工作结束以前试加工作电压，应满足哪\n些条件？",
    "a": "答: 检修工作结束以前，若需将设备试加工作电压，应满\n足以下条件：\n1）全体工作人员撤离工作地点；\n2）将该系统的所有工作票收回，拆除临时遮栏、接\n地线和标示牌，恢复常设遮栏；3）应在工作负责\n人和运行人员进行全面检查无误\n后，由运行人员进行加压试验。",
    "o": null,
