    "q": "在什么情况下使用母联断路器保护？",
    "a": "答：（1）用母联断路器给检修后的母线充电时；\n（2）用母联断路器代替线路断路器工作时；\n（3）线路继电器保护检验和更改定值时；\n（4）母联断路器必须具备代替线路断路器运行的保护与自\n动装置。",
