    "type": "C",
    "type_name": "简答题",
    "q": "中性点直接接地运行方式有哪些特点？",
    "a": "答：（1）发生单相接地时形成单相对地短路电流，断路器\n跳闸，中断供电，影响供电可靠性，为弥补上述不足，广泛采\n用自动重合闸装置；\n（2）单相接地时短路电流很大，产生一个很强的磁场，在\n附近的弱电线路上（如通信线路等）感应一个很大的电势，引\n起设备损坏；\n（3）单相接地故障时，非故障相对地电压不会升高。",
    "o": null,
