    "type": "C",
    "type_name": "简答题",
    "q": "交直流两用型钳型电流表的工作原理是怎样\n的？",
    "a": "答：交直流两用型钳型电流表是采用电磁等测量机构原理\n构成的，卡在铁芯钳口中的被测电流导线相当于电磁系测量机\n构中的固定线圈，在铁芯中产生磁场，而位于铁芯钳口中间可\n动铁片在磁场作用下发生偏转，带动指针指示出被测电流的大\n小。\n\n89",
