    "a": "答：电气设备操作后的位置检查应以设备实际位置为准，\n无法看到实际位置时，可通过设备机械位置指示、电气指示、\n仪表及各种遥测、遥信信号的变化，且至少应有两个及以上指\n示已同时发生对应变化，才能确认该设备已操作到位。",
