    "q": "什么是蓄电池的自放电现象？",
    "a": "答：由于蓄电\n池电解液中所含金属杂质沉淀在负极板上，\n以及极板本身活性物质中也含有金属杂质，因此在负极板上形\n成局部的短路回路，就构成了蓄电池的自放电现象。",
    "o": null,
