    "q": "直流系统两点接地的危害是什么？",
    "a": "答：直流系统发生两点接地后的危害是：\n（1）构成两点接地短路，将造成信号装置、继电保护和断\n路器的误动作或拒动作；\n（2）两点接地引起熔断器的熔断，造成直流中断。",
