    "type": "C",
    "type_name": "简答题",
    "q": "简述水轮发电机组调速器的基本作用？",
    "a": "答：调速器的基本作用是自动测量发电机出口频率和给定\n值之间的偏差，据此偏差控制水轮机导水叶开度，改变进入水\n轮机的流量，维持频率在一定范围内，调速器按其静态转差系\n数的大小自动分配系统中的负荷。",
    "o": null,
