    "q": "什么是射流泵？它有何优缺点？",
    "a": "答：射流泵是一种利用液体或气体射流形成的负压抽吸液\n体，使被抽液体增加能量的机械设备。优点是：无转动部分，\n结构简单，紧凑，不怕潮湿，工作可靠。缺点是：效率较低，\n不易维护。",
    "o": null,
