    "type_name": "简答题",
    "q": "什么叫发电机的失磁？引起失磁的原因是什\n么？",
    "a": "答：发电机失磁是指正常运行的发电机的励磁绕组突然失\n去全部或部分励磁电流。引起失磁的原因主要是由于励磁回路\n开路（灭磁开关误动作，励磁调节器装置开关误动）、短路或励\n磁机励磁电源消失或转子绕组故障等。",
    "o": null,
