    "type_name": "简答题",
    "q": "厂用变压器过流保护为何延时，能否作为速断\n保护的后备保护？",
    "a": "答：过流保护之所以延时，是因为它主要保护的是变压器\n低压侧的短路故障，是为了使所配备的保护选择性地切除故障。\n\n过流保护能作为速断保护的后备保护。",
