    "type_name": "简答题",
    "q": "什么叫跨步电压？其允许值多少？",
    "a": "答：由于\n接地短路电流的影响，在附近地面将有不同电位\n分布，人步入该范围内，两脚跨距之间电位差称为跨步电压，\n此跨距为0.8m，正常运行，不允许超过40V。",
