    "type": "C",
    "type_name": "简答题",
    "q": "电压互感器在运行中二次侧为什么不许短\n路？",
    "a": "答：电压互感器二次侧电压为100V，且接于仪表和继电器\n的电压线圈。电压互感器是一电压源，内阻很小，容量亦小，\n一次线圈导线很细，若二次侧短路，则二次侧通过很大电流，\n不仅影响测量表计及引起保护与自动装置误动，甚至会损坏电\n压互感器。",
