    "a": "答：第一种工作票工作许可人在完成施工现场的安全措施\n后，还应完成以下手续，工作班方可开始工作：\n（1）会同工作负责人到现场再次检查所做的安全措施，对\n具体的设备指明实际的隔离措施，证明检修设备确无电压。\n（2）对工作负责人指明带电设备的位置和工作过程中的注\n意事项。和工作负责人在工作票上分别确认、签名。",
