    "type_name": "简答题",
    "q": "电压互感器或电流互感器遇有哪些情况应立\n即停电处理？",
    "a": "答：主要有以下情况：①高压熔丝连续熔断；②互感器\n过热，流油有焦味；③内部有放电声；④引线接头断开放电。",
