    "type": "C",
    "type_name": "简答题",
    "q": "中性点运行方式有哪几种类型？各用在什么\n场合？",
    "a": "答：中性点运行方式有：中性点直接接地、中性点不接地\n和中性点经消弧线圈接地三种方式。第一种一般在110kV 及以\n上系统应用；后两种应用于63kV 及以下系统；低压用电系统\n（380/220V）习惯上采用第一种方式以获得三相四线制供电方\n式。",
    "o": null,
