    "type_name": "简答题",
    "q": "SF6 配电装置发生大量泄漏等紧急情况时，如\n何处理？",
    "a": "答：SF6 配电装置发生大量泄漏等紧急情况时，人员应迅\n速撤出现场，开启所有排风机进行排风。未配戴隔离式防毒面\n具人员禁止入内。只有经过充分的自然排风或恢复排风后，人\n\n99\n员才准进入。发生设备防爆膜破裂时，应停电处理,并用汽油或\n丙酮擦试干净。",
    "o": null,
