    "id": "Je3C4132",
    "type": "C",
    "type_name": "简答题",
    "q": "变压器等值老化原理的内容是什么？",
    "a": "答：等\n值老化原理就是变压器在部分运行时间内绕组温度\n低于95℃或欠负荷，则在另一部分时间内可以使绕组温度高于\n95℃或过负荷，只要使过负荷时间内多损耗的寿命等于变压器\n在欠负荷时间内所少损耗的寿命，两者相互抵消，就仍然可以\n保持正常的使用寿命。",
    "o": null,
