    "q": "有的线路停电时，为什么先断开重合闸？而送\n电正常后又要再投入？",
    "a": "答：电气重合闸一般按照“不对应”方式来启动，部分类\n型的重合闸会在断开短路器时误动；如果送电前重合闸还在投\n入，送电时会造成重合闸误合，送电后有可能重合闸拒动。",
