    "type_name": "简答题",
    "q": "少油断路器油面降低、SF6 断路器气压降低时\n如何处理？",
    "a": "答：因为在这两种情况下，断路器的灭弧能力降低乃至丧\n失，此时不允许该断路器带负荷分闸。为了防止此时保护动作\n于该断路器跳闸，应请示有关人员后切断开有关保护电源（不\n能切保护电源的应断开其跳闸回路），将该开关所带的负荷转移\n或停电，再断开其上一级供电断路器后再将该断路器分闸，做\n好措施，联系检修处理。",
    "o": null,
