    "a": "答：电气方面不平衡力主要有：\n（1）不均衡的间隙造成磁拉力不均衡；\n（2）发电机转子线圈间短路后，造成不均衡磁拉力增大；\n（3）三相负荷不平衡产生负序电流和负序磁场，形成交变\n应力。",
