    "a": "答：油劣化的根本原因是油和空气中的氧起了作用，油被\n氧化了。加速油劣化的因素有水分、温度、空气、天然光线、\n电流和其他因素，如金属的氧化作用、检修后清洗不良等。",
    "o": null,
