    "q": "轴电流有什么危害？",
    "a": "答：由于电流通过主\n轴、轴承、机座而接地，从而在轴颈\n和轴瓦之间产生小电弧的侵蚀作用，破坏油膜使轴承合金逐渐\n黏吸到轴颈上去，破坏轴瓦的良好工作面，引起轴承的过热，\n甚至把轴承合金熔化，此外，由于电流的长期电解作用，也会\n使润滑油变质发黑，降低润滑性能，使轴承温度升高。",
    "o": null,
