    "type": "C",
    "type_name": "简答题",
    "q": "什么是变压器绝缘老化的“六度法则”？",
    "a": "答：当变压器绕组绝缘温度在80～130℃范围内，温度每\n\n升高6℃，其绝缘老化速度将增加一倍，即温度每升高6℃，绝\n缘寿命就降低1/2，这就是绝缘老化的“六度法则”。",
    "o": null,
