    "type_name": "简答题",
    "q": "什么是消防工作中的“ 预防为主，防消结\n台” ？",
    "a": "答：我国消防工作的方针是：“预防为主，防消结合”。“预\n防为主”就是要把预防火灾的工作放在首要的地位，“防消结\n合”，就是在积极做好防火工作的同时，在组织上、思想上、物\n资上做好灭火战新的装备，一旦发生火灾，能迅速，有效地将\n火灾扑灭。“防”和“消”是相辅相成的两个方面，缺一不可。",
    "o": null,
