    "a": "答：有功功率是保持用电设备正常运行所需的电功率，也\n就是将电能转换为其他形式能量(机械能、光能、热能)的电\n功率。\n无功功率是用于电路内电场与磁场的交换，并用来在电气\n设备中建立和维持磁场的电功率。\n简\n答\n题",
