    "a": "答：短路对设备的危害，概括起来，一是电流的热效应使\n设备烧坏、损坏绝缘，二是电动力使设备变形、毁坏，对系统\n的危害是使供电受阻，甚至造成系统稳定的破坏，使之出现非\n故障部分的大面积停电。",
