    "q": "目前大型汽轮发电机组采用什么冷却方式?",
    "a": "答：目前大型汽轮发电机多采用水、水、空冷却系统(双\n水内冷)和水、氢、氢冷却系统。其中水、氢、氢冷却的发电\n机冷却系统包括三个支系统，即氢气控制系统、密封供油系统\n和发电机定子冷却水系统；水、水、空冷却系统需闭式循环冷\n却水系统。\n简\n答\n题\n鉴\n定\n试\n题\n库\n\n114",
