    "type": "C",
    "type_name": "简答题",
    "q": "电容器的放电电阻应符合哪些要求?",
    "a": "答：(1)应保证电容器组在放电1min 后，电容器电压\nUc<65V。\n(2)在正常运行时的电力损失每千乏电容量的有功损耗不\n超过1W。\n(3) 应装在电容器开关的负荷侧，并和电容器永久接在一起。",
