    "q": "如何提高用电设备的自然功率因数?",
    "a": "答：(1)合理选择电动机的容量，使其接近满负荷运行。\n(2)对于平均负荷小于40%的感应电动机，换用小容量电\n动机或改定子绕组三角形接线为星形接线。\n(3)改善电气设备的运行方式，限制空载运行。\n(4)正确选择变压器的容量，提高变压器的负荷率。\n(5)提高感应电动机的检修质量。",
    "o": null,
