    "type": "C",
    "type_name": "简答题",
    "q": "油断路器跳闸失灵有哪些原因?",
    "a": "答：(1)电路方面的原因有操作电压过低；操作熔丝及跳\n闸电路内各件接触不良；断线。\n(2)机械方面的原因有操动机构有异常、滑动杆及缓冲杆\n卡涩。\nJd2C507 0\n手动操作隔离开关的要点有哪些?\n答：(1)合闸时：核对操作项目；操作迅速果断，但不要\n用力过猛；操作完毕，要检查合闸良好。\n(2) 拉闸时：开始动作要慢而谨慎，闸刀离开端触头时应\n迅速拉开；拉闸完毕，要检查断开良好。",
