    "type_name": "简答题",
    "q": "引起电压互感器的高压熔断器熔丝熔断的原\n因是什么?",
    "a": "答：可能有四方面的原因：\n(1) 系统发生单相间歇电弧接地；\n(2)系统发生铁磁谐振；\n(3)电压互感器内部发生单相接地或层间、相间短路故障；\n(4)电压互感器二次回路发生短路而二次侧熔丝选择太粗\n而未熔断时，可能造成高压侧熔丝熔断。",
    "o": null,
    "q_img": "q2_question_images/E_Jd1C2077_q.png",
