    "q": "变压器的温度与温升有什么区别?",
    "a": "答：变压器的温度是指变压器本体各部位的温度，温升是\n指变压器本体温度与周围环境温度的差值。\n统有无漏油现象；④变压器负荷电流、温度是否在允许范围内；\n⑤变压器声音是否正常等。\n鉴\n定\n试\n题\n库\n简\n答\n题\n\n132",
