    "id": "E_Je4C2105",
    "type": "C",
    "type_name": "简答题",
    "q": "变压器运行中应做哪些检查?",
    "a": "答：(1)变压器声音是否正常；\n(2)瓷套管是否清洁，有无破损、裂纹及放电痕迹；\n(3)油位、油色是否正常，有无渗油现象；\n(4)变压器温度是否正常；\n(5)变压器接地应完好；\n(6)电压值、电流值是否正常；\n(7) 各部位螺丝有无松动；\n(8)一次、二次引线接头有无松动和过热现象。",
    "o": null,
    "q_img": "q2_question_images/E_Je4C2105_q.png",
