    "type": "C",
    "type_name": "简答题",
    "q": "为什么变压器铁芯及其他所有金属构件要可\n靠接地?",
    "a": "答：变压器在试验或运行中，由于静电感应，铁芯和不接\n地金属件会产生悬浮电位。由于在电场中所处的位置不同，产\n生的电位也不同。当金属件之间或金属件对其他部件的电位差\n超过其绝缘强度时就会放电，因此金属构件及铁芯要可靠接地。",
    "o": null,
