    "id": "E_Je3C3119",
    "type": "C",
    "type_name": "简答题",
    "q": "什么叫电力系统的动态稳定?",
    "a": "答：电力系统运行的动态稳定性是指当正常运行的电力系\n统受到较大的扰动，它的功率平衡受到相当大的波动时，将过\n渡到一种新的运行状态或回到原来的运行状态，继续保持同步\n运行的能力。",
    "o": null,
