    "type": "C",
    "type_name": "简答题",
    "q": "提高电力系统动态稳定的措施有哪些?",
    "a": "答：提高动态稳定的常用措施有：\n①快速切除短路故障；②采用自动重合闸装置；③采用\n电气制动和机械制动；④变压器中性点经小电阻接地；⑤设\n置开关站和采用强行串联电容补偿；⑥采用连锁切机；⑦快\n速控制调速汽门等。",
    "o": null,
