    "a": "答：这是为了检查变压器内部绝缘的薄弱点和考核变压器\n的机械强度，以及继电保护装置能否躲过励磁涌流而不发生误\n鉴\n定\n试\n题\n库\n简\n答\n题\n\n136\n动作。",
