    "type": "C",
    "type_name": "简答题",
    "q": "在中性点非直接接地的系统中，如何防止谐振\n过电压?",
    "a": "答：选用励磁特性较好的电磁式电压互感器或电容式电压\n互感器；在电磁式电压互感器的开口三角线圈内(35kV 以下系\n统)装设10～100Ω的阻尼电阻；在10kV及以下电压的母线上，\n装设中性点接地的星形接线电容器组等。",
