    "type_name": "简答题",
    "q": "什么叫变压器的并联运行?",
    "a": "答：变压器的并联运行，就是将两台或两台以上变压器的\n一次绕组并联在同一电压的母线上，二次绕组并联在另一电压\n的母线上运行。",
