    "q": "变压器油枕和防爆管之间的小连通管起什么\n鉴\n定\n试\n题\n库\n简\n答\n题\n\n142\n简\n答\n题\n鉴\n定\n试\n题\n库\n作用?",
    "a": "答：此小管使防爆管的上部空间与油枕的上部空间连通，\n让两个空间内压力相等，油面高度保持相同。",
