    "q": "如何改变三相异步电动机的转子转向?",
    "a": "答：将异步电动机的三相电源线任意两相对调，就改变了\n绕组中三相电流的相序，旋转磁场的方向就随之改变，也就改\n变了转子的旋转方向。\nJe1C215 2\n电动机的铭牌上有哪些主要数据?\n答：主要有额定功率、额定电压、额定电流、额定转数、\n相数、型号、绝缘等级、工作方式、允许温升、功率因数、重\n量、出厂日期等。",
