    "q": "变压器油色不正常时，应如何处理?",
    "a": "答：在运行中，如果发现变压器油位计内油的颜色发生变\n化，应取油样进行分析化验。若油位骤然变化，油中出现炭质，\n并有其他不正常现象时，则应立即将变压器停止运行。",
