    "a": "答：晶体三极管通常称为晶体管，它由三块半导体材料按\n一定形式组合而成。它有两个PN结(发射结和集电结),三个\n电极(基极、发射极和集电极),一般用字母b、e和c 表示。\n基极b 接在中间的半导体上，发射极e 和集电极c 分别接在基\n极两边的半导体上。",
