    "type_name": "简答题",
    "q": "自动电源自投入装置( BZT) 是由哪几部分组\n成的?各部分的作用是什么?",
    "a": "答：自动电源自投入装置由低电压起动部分和自动重合闸\n部分组成。\n低压起动部分的作用是：当电压降到低压保护动作值时跳\n闸，备用电源投入；自动重合闸部分的作用是：在工作电源断\n路器断开之后，BZT装置自动投入备用电源的断路器。",
