    "q": "继电保护装置的基本任务是什么?\n简\n答\n题\n鉴\n定\n试\n题\n库\n\n149",
    "a": "答：当电力系统发生故障时，利用一些电气自动装置将故\n障部分从电力系统中迅速切除，当发生异常时，及时发出信\n号，以达到缩小故障范围，减少故障损失，保证系统安全运行\n的目的。",
