    "a": "答：配电装置中的母线涂漆有利于母线散热，可使容许负\n荷提高12%～15%;便于值班人员，检修人员识别直流的极性\n和交流的相别，铜母线涂漆还可以起到防锈作用。\n简\n答\n题\n鉴\n定\n试\n题\n库\n\n150\n简\n答\n题",
