    "q": "如图D-16 所示的电路，已知I=10A, I₁=6A,\n电阻R₁=3Ω,R₂=1Ω,R\n₃=2Ω,求电流表PA1 和PA2的读数是\n多少。\n图D-16\n解：据基尔霍夫第一定律得出\nI₂=I-I₁=10-6=4(A)\nR₁ 上的压降：UR₁=I₁R₁=6×3=18(V)\n设c 点电位为0,则a 点电位Va=18V\nR₂上的压降：UR₂ =I₂R₂=4×1=4(V)\n则b 点电位V₆=V.-UR₂=18-4=14(V)\n故R₃ 上的压降UR₃=V₆-V.=14-0=14(V)\n(A)\n则电流表PA1的读数是：I₁+I₃=6+7=13(A)\n电流表PA2的读数是：I₂-I₃=7-4=3(A)",
