    "type_name": "计算题",
    "q": "一台长6mm 电钻，额定电压为110V, 功率为\n80W。而现有电源的电压为220V, 为了急于使用电钻，手中只\n有一些电压220V, 功率为40、60、100W 的灯泡，试求怎样接\n入这些灯泡才能使电钻正常工作?\n解：要使电钻在220V 下正常工作，必须串入灯泡进行降\n压，应降去的电压U₁=U-Un=220-110=110(V)\n如果用110V、80W 灯泡，直接串入电钻回路就可以了。\n但现在只有220V,40、60、100W 灯泡，那要求多大瓦数的灯\n鉴\n定\n试\n题\n库\n\n207\n泡在110V电压下功率为80W 呢?\n根据灯泡功率与电压平方成正比，即灯泡电压降到原来的\n时，它的功率降到原来",
    "a": "答：用现有灯泡40、60、100 W 凑成320W 即可。方法很\n多，我们采用两个100W, 两个60W 四个灯泡并联后再与电钻\n串联使用，电钻就可以在220V电压下正常工作。",
