    "q": "某工厂单相供电线路的额定电压Un=10kV,平\n均负荷P=400kW, 无功功率Q=260kvar, 功率因数较低。现要\n将该厂的功率因数提高到0.9,需要装多少补偿电容?\n解：补偿电容前的功率因数为\ncosφ=P/S=PI√P²+Q²=4001√400²+260²=0.84\n于是可得功率因数角φ₁=33°\n又因补偿后的功率因数cosφ=0.9, 所以功率因数角φ=25.8°\n需安装的补偿电容为\nC=P/(wU²)(tanφ₁-tanφ)\n=(400×10³)/2×3.14×50×(10×10³)²](tan33°-tan\n25.8°)\n=2.1×10⁻⁶F=2.1(μF)",
    "a": "答：需要装补偿电容2.1μF。",
